{
  "build": [
    {
      "slot": "body",
      "from_character": "Wojak",
      "trait": "Wojak body: thin pale human body, narrow slumped shoulders, simple thin lineart, plain and sad",
      "how": "The torso is a thin, narrow-shouldered, slumped humanoid frame drawn with clean minimalist lineart."
    },
    {
      "slot": "head",
      "from_character": "Pepe the Frog",
      "trait": "wide flat frog head, no neck, eyes sitting on top",
      "how": "A wide, flat amphibian frog head with twin eye-domes on top sits directly on the narrow slumped shoulders without a neck."
    },
    {
      "slot": "skin_or_palette",
      "from_character": "NPC Wojak",
      "trait": "flat grey skin, no colour at all",
      "how": "The entire skin and short fur of the creature is rendered in flat, deadpan monochrome NPC Wojak grey."
    },
    {
      "slot": "face",
      "from_character": "NPC Wojak",
      "trait": "NPC face: completely blank expression, sharp pointed triangular nose, zero emotion",
      "how": "The middle of the wide frog head features NPC Wojak's sharp, pointed, geometric triangular nose and blank, unbothered facial planes."
    },
    {
      "slot": "mouth",
      "from_character": "Pepe the Frog",
      "trait": "Pepe lips: thick, wide reddish-brown lips in a flat smug line across the whole lower face",
      "how": "Pepe's unmistakable thick, wide reddish-brown lips stretch horizontally across the full width of the face in a flat, deadpan line."
    },
    {
      "slot": "eyes",
      "from_character": "Doge",
      "trait": "the Doge look: eyes shifted to the side in a sideways side-eye, raised inner eyebrows, calm judging stare, plus small triangular upright Shiba ears on the head",
      "how": "Inside the top frog eye-bulges, the eyes give the iconic Doge sideways side-eye with raised inner brows, flanked by two small triangular upright Doge ears."
    },
    {
      "slot": "jaw",
      "from_character": "Gigachad",
      "trait": "Gigachad jaw: extremely chiselled square jawline and sharp cheekbones with a short dark trimmed beard",
      "how": "Beneath the wide Pepe lips, the lower face juts out into an impossibly chiselled, square Gigachad jawline covered in a neat dark-grey trimmed beard."
    },
    {
      "slot": "arms",
      "from_character": "Harambe",
      "trait": "silverback gorilla arms: long heavy dark-furred gorilla arms reaching down to the ankles",
      "how": "Hanging from the narrow Wojak shoulders are massive, disproportionately long, heavy gorilla arms covered in dark charcoal-grey fur."
    },
    {
      "slot": "feet",
      "from_character": "Tralalero Tralala",
      "trait": "Tralalero sneakers: three legs each wearing a bright blue Nike-style sneaker with a white swoosh",
      "how": "The thin torso stands on three legs, each shod in an oversized bright blue Nike-style sneaker with a crisp white swoosh."
    },
    {
      "slot": "accessory",
      "from_character": "Tung Tung Tung Sahur",
      "trait": "a wooden baseball bat with visible wood-grain rings held in one hand",
      "how": "One huge gorilla hand casually grips the warm orange-brown wooden baseball bat of Tung Tung Tung Sahur."
    },
    {
      "slot": "pose",
      "from_character": "Doge",
      "trait": "head tilted and turned over the shoulder, viewed from a slight three-quarter angle",
      "how": "The creature stands in a slight three-quarter turn, looking back over its slumped shoulder toward the viewer."
    },
    {
      "slot": "style",
      "from_character": "Trollface",
      "trait": "rough black-and-white MS-Paint scribble lineart and deep wrinkly cheek creases",
      "how": "The entire character is outlined in slightly wobbly, expressive MS-Paint black lineart with deep Trollface-style wrinkle lines framing the edges of the wide lips."
    }
  ],
  "base_character": "Wojak",
  "concept": {
    "form": "A slumped, thin-bodied humanoid creature with a wide flat frog head, a massive chiselled jaw, huge hanging gorilla arms, and three sneaker-clad legs, holding a wooden baseball bat.",
    "face": "A wide flat Pepe the Frog head topped with small upright Doge ears and Doge sideways-glancing eyes, NPC Wojak's sharp pointed triangular nose in the center, Pepe's thick wide reddish-brown lips framed by Trollface's wrinkly cheek creases, all resting atop Gigachad's square bearded jawline.",
    "body_and_colors": "A thin, narrow-shouldered Wojak torso with huge hanging Harambe gorilla arms and three Tralalero Tralala legs; unified in a strict 4-colour palette of flat NPC Wojak grey skin, dark charcoal-grey gorilla fur and beard, Pepe reddish-brown lips, bright blue sneakers with white swooshes, and a warm brown wooden bat.",
    "pose": "Standing on three sneakered feet in a slight three-quarter turn, shoulders slumped, head tilted back over the shoulder giving the Doge side-eye while resting a wooden baseball bat on the ground.",
    "vibe": "Programmed, unbothered superiority—when you have zero original thoughts left in your grey NPC brain, yet you still mog everyone in the room.",
    "signature": "The wide flat grey Pepe frog head combining NPC Wojak's sharp triangle nose, thick reddish-brown Pepe lips, and a massive square Gigachad jaw."
  },
  "name_ideas": [
    "Zorbo",
    "Plonk",
    "Grimpo"
  ],
  "caption": "When the dialogue tree ends so you just mog.",
  "lore": "Spawned in an unrendered test map when seven meme timelines collided at 3 AM, Zorbo wanders the void on three sneakers, waiting for a dialogue prompt that never comes.",
  "image_prompt": "A single unified meme character combining famous meme parts: the thin, narrow-shouldered slumped body of Wojak, the wide flat frog head of Pepe the Frog sitting directly on the shoulders, Pepe the Frog's thick wide reddish-brown lips stretching across the face, NPC Wojak's flat grey skin and sharp pointed triangular nose, Doge the Shiba Inu's sideways side-eye stare and small upright triangular ears on top of the frog head, Gigachad's extremely chiselled square jawline with a short dark grey beard underneath the frog lips, Trollface's wrinkly cheek folds and rough MS-Paint black outline style, Harambe the gorilla's massive long heavy dark-grey furred arms hanging down from the thin shoulders, Tralalero Tralala's three legs each wearing a bright blue Nike sneaker with a white swoosh, and Tung Tung Tung Sahur's brown wooden baseball bat with wood-grain rings held in one gorilla hand, posed in Doge's slight three-quarter turn looking back over the shoulder. One single character, full body, centered, clean confident lineart, flat colours, one consistent palette of flat NPC grey, charcoal grey, reddish-brown, wood brown, and bright sneaker blue, expressive deadpan face, on a solid single-colour pale off-white background; no shadows, no gradients, no lighting effects, no floor, no background elements, no text, no watermark."
}
